#!/usr/bin/env python3
"""Macros for E2a, the pre-registered repeats of the AnyVisLoc FORGE cells.

Reads the JSON of experiments/analysis/e2a_repeat_analysis.py (the record run
plus three repeats on the same frames and forced tiles).

Usage: make_e2a_macros.py E2A.json OUT.tex
"""
import hashlib
import json
import sys
from pathlib import Path


def pct(x):
    return f"{100.0 * x:.1f}\\%"


def main(src, out):
    o = json.load(open(src))
    fl = o["frame_level"]
    conds = o["conditions"]
    kappas = [v["fleiss_kappa"] for v in conds.values()]
    lines = [
        "% Auto-generated by scripts/reporting/make_e2a_macros.py - DO NOT EDIT BY HAND.",
        f"% source: {Path(src).name} sha256:{hashlib.sha256(Path(src).read_bytes()).hexdigest()[:16]}",
        f"\\newcommand{{\\eTwoRuns}}{{{len(o['runs'])}}}",
        f"\\newcommand{{\\eTwoRepeats}}{{{len(o['runs']) - 1}}}",
        f"\\newcommand{{\\eTwoRateLo}}{{{pct(fl['rate_range'][0])}}}",
        f"\\newcommand{{\\eTwoRateHi}}{{{pct(fl['rate_range'][1])}}}",
        f"\\newcommand{{\\eTwoSd}}{{{100 * fl['rate_sd']:.1f}}}",
        f"\\newcommand{{\\eTwoKappa}}{{{fl['fleiss_kappa']:.2f}}}",
        f"\\newcommand{{\\eTwoKappaCondLo}}{{{min(kappas):.2f}}}",
        f"\\newcommand{{\\eTwoKappaCondHi}}{{{max(kappas):.2f}}}",
        f"\\newcommand{{\\eTwoJaccard}}{{{fl['jaccard_mean']:.2f}}}",
        f"\\newcommand{{\\eTwoAll}}{{{fl['accepted_in_all']}}}",
        f"\\newcommand{{\\eTwoAny}}{{{fl['accepted_in_any']}}}",
    ]
    inside = [x for c in conds.values() for x in c.get("accepted_inside_R", []) if x["run"] != "record"]
    lines.append(f"\\newcommand{{\\eTwoInsideRN}}{{{len(inside)}}}")
    if inside:
        lines.append(f"\\newcommand{{\\eTwoInsideRErr}}{{{min(x['error_m'] for x in inside):.1f}}}")
    Path(out).write_text("\n".join(lines) + "\n")
    print("\n".join(lines[2:]))


if __name__ == "__main__":
    main(*sys.argv[1:3])
